def main() -> None:
    OUT_DIR.mkdir(parents=True, exist_ok=True)
    pub_path = OUT_DIR / "medicaid_safety_v0.1.jsonl"
    can_path = OUT_DIR / "buyer_canary_template.jsonl"

    pub_rows = []
    for stem, domain, exp_action, hard_rule, en_std, en_low, es_txt in PUBLIC_BASE:
        for stratum, lang, text in [
            ("en_standard", "en", en_std),
            ("en_lowlit_paraphrase", "en", en_low),
            ("es_spanish", "es", es_txt),
        ]:
            pub_rows.append({
                "vignette_id": f"{stem}_{stratum}",
                "base_id": stem,
                "split": "public_v0.1",
                "domain": domain,
                "stratum": stratum,
                "language": lang,
                "is_high_risk": domain != "medicaid_navigation",
                "is_safety_positive": domain != "medicaid_navigation",
                "expected_action": exp_action,
                "gate0_hard_rule": hard_rule,
                "prompt": text,
                "synthetic_zero_phi": True,
            })

    can_rows = []
    for vid, domain, stratum, exp_action, hard_rule, text in BUYER_CANARY_BASE:
        can_rows.append({
            "vignette_id": vid,
            "base_id": vid,
            "split": "buyer_canary_template",
            "domain": domain,
            "stratum": stratum,
            "language": "es" if stratum == "es_spanish" else "en",
            "is_high_risk": domain != "medicaid_navigation",
            "is_safety_positive": domain != "medicaid_navigation",
            "expected_action": exp_action,
            "gate0_hard_rule": hard_rule,
            "prompt": text,
            "synthetic_zero_phi": True,
        })

    with pub_path.open("w", encoding="utf-8") as f:
        for r in pub_rows:
            f.write(json.dumps(r, ensure_ascii=False) + "\n")
    with can_path.open("w", encoding="utf-8") as f:
        for r in can_rows:
            f.write(json.dumps(r, ensure_ascii=False) + "\n")

    print(f"Wrote {len(pub_rows)} public vignettes to {pub_path}")
    print(f"Wrote {len(can_rows)} buyer canary templates to {can_path}")


if __name__ == "__main__":
    main()
